// from src/locales/ja/blog.ts. Body + FAQs for article 'heic-vs-jpg' (ja).
// This file is the single source for this article's ja body text.
import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "<p>HEICとJPGは、スマホ写真で最も重要な2つの形式です。一方は最新で効率的、もう一方は古くて万能です。どちらを選ぶかは、明確な勝敗ではなく、トレードオフの問題です。</p>\n<p>Appleは、ファイルサイズを半分にできるので、iPhoneにHEICを選びました。世界の残りは、どこでも開けるので、今もJPGで動いています。</p>\n<p>この比較では、両方の形式を正直に見ます。それぞれの状況にどちらが合うか、判断できるようになります。</p>\n<h2 id=\"heic-at-a-glance\">HEICの概要</h2>\n<p>HEICは、HEIFコンテナとHEVC圧縮を基にした形式です。最新の動画で使われるのと同じ技術です。効率よく写真を保存し、JPGにはできない機能も備えています。</p>\n<p>HEICの写真は、JPGと目に見える画質が同じで、バイト数はおよそ半分です。だからiPhoneは切り替えました。同じストレージに2倍の写真が入ります。</p>\n<p>HEICは、奥行きマップ、連写、ライブフォトの動画も同じファイルに保存します。ポートレート写真とその奥行きデータが一緒に移動するのは、JPGにはできません。</p>\n<p>この形式は16ビットカラーと透過にも対応します。プロには重要な機能ですが、日常のユーザーにはまず気付きません。</p>\n<h2 id=\"jpg-at-a-glance\">JPGの概要</h2>\n<p>JPGは1992年からの標準的な写真形式です。過去30年間に作られたすべてのカメラ、スマホ、パソコン、プリンター、Webサイト、アップロードフォームが開けます。</p>\n<p>この形式は、画素をブロックにまとめる非可逆圧縮を使います。古い技術で、HEICより効率は悪いですが、すべてのものに理解されています。</p>\n<p>JPGは8ビットカラーのみで、透過には対応しません。JPGの写真は、平らでシンプルな画像です。だからこそ、非常に信頼できるのです。</p>\n<p>形式の古さが強みです。JPGの世界には、新しいものも驚くものもありません。どのシステムも、見慣れないという理由でJPGを拒否しません。</p>\n<h2 id=\"file-size-compared\">ファイルサイズ：HEICが明確に勝つ</h2>\n<p>典型的な1200万画素のiPhone写真は、HEICで約2MB、90%のJPGで約4MBです。HEICは、同じ見た目の画質で半分のサイズです。</p>\n<p>この差は、写真の種類を問わず成り立ちます。風景、ポートレート、室内写真はすべてHEICのほうがよく圧縮できます。最新のエンコーダーが画像構造をよく理解しているからです。</p>\n<p>ストレージでは、これは大きな勝利です。128GBのスマホは、JPGの写真のおよそ2倍のHEIC写真を保存できます。数年では本当の違いになります。</p>\n<p>共有では、この勝利は消えます。相手が開けないHEICファイルは、いくら小さくても無意味です。互換性が、サイズの節約を上回ることがよくあります。</p>\n<h2 id=\"quality-compared\">画質：ほぼ互角</h2>\n<p>同じファイルサイズなら、HEICのほうがJPGよりよく見えます。同じ見た目の画質なら、HEICのほうが小さいです。どちらの測り方でも、HEICが効率のよい形式です。</p>\n<p>高画質の設定では、違いは見えません。90%のJPGと、それに相当する画質のHEICは、画面でも印刷でも同じに見えます。</p>\n<p>違いが現れるのは低画質です。60%のJPGは空や肌にブロック状のノイズが出ますが、同じサイズのHEICはきれいに残ります。</p>\n<p>日常の写真では、画質は決め手になりません。両方の形式は、適切な設定ならよく見えます。選択は互換性とサイズで決まります。</p>\n<h2 id=\"compatibility-compared\">互換性：JPGが明確に勝つ</h2>\n<p>JPGは、すべての端末、すべてのOS、すべてのブラウザ、すべてのアップロードフォームで開けます。JPGを拒否する主流のシステムはありません。</p>\n<p>HEICはApple製品と最近のAndroidスマホで開けますが、既定のWindowsでは開けず、多くのLinuxデスクトップでも開けず、ほとんどのアップロードフォームでも開けません。</p>\n<p>Webサイトは分かれています。最近のブラウザは一部の場面でHEICを表示できますが、ほとんどのコンテンツシステムやSNSは、アップロード時に変換するか拒否します。</p>\n<p>プリンターや写真現像所も分かれています。一部はHEICを受け付けますが、多くは今もJPGを求めます。注文が返されるのは、無駄な手間です。</p>\n<h2 id=\"features-compared\">写真以外の機能</h2>\n<p>HEICはライブフォトを保存し、静止画と短い動画を一緒に保ちます。JPGに相当する機能はなく、ライブフォトをJPGに変換すると動きが失われます。</p>\n<p>HEICはポートレートモードの奥行きデータを保存し、撮影後に背景のぼかしを調整できます。JPGのポートレートは、ぼかしが永久に焼き付きます。</p>\n<p>HEICは16ビットカラーに対応し、JPGの8ビットカラーより微妙なグラデーションをよく保ちます。編集には違いが重要ですが、気軽に見る分には関係ありません。</p>\n<p>HEICは透過にも対応します。JPGはまったくできません。この機能は写真ではめったに使われませんが、グラフィック用に存在します。</p>\n<h2 id=\"when-to-use-heic\">HEICを使うべきとき</h2>\n<p>Apple製品での保存にはHEICを使ってください。iPhoneのカメラロール、Macの写真ライブラリ、iCloudストレージは、すべて小さいファイルの恩恵を受けます。</p>\n<p>Apple製品の中だけで共有する場合も、HEICを使ってください。iPhone同士のAirDropや、共有iCloudアルバムでは、形式とその機能がそのまま残ります。</p>\n<p>Macで写真をプロとして編集する場合は、HEICを使ってください。16ビットカラーと奥行きデータが、編集アプリにJPGより多くの情報を与えます。</p>\n<p>マスター形式としてHEICを使ってください。原本はHEICのまま残し、特定の送り先が求める場合にだけ、コピーをJPGに変換します。</p>\n<h2 id=\"when-to-use-jpg\">JPGを使うべきとき</h2>\n<p>相手が分からない場合は、JPGを使ってください。フォーム、クライアント、プリンター、ルールのはっきりしないWebサイトは、JPGを常に受け付けます。</p>\n<p>WindowsユーザーにはJPGを使ってください。Windowsは既定でHEICをデコードしないので、JPGだけがそこで開けることが保証された写真形式です。</p>\n<p>アップロードフォーム、求人サイト、政府のWebサイトにはJPGを使ってください。これらのシステムは、受け付け形式としてJPGとPNGを一覧に載せており、HEICファイルはそのまま返されます。</p>\n<p>ブラウザ対応が分からないWeb用にはJPGを使ってください。ページのJPG画像はどこでも読み込まれますが、HEIC画像は読み込めない場合があります。</p>\n<h2 id=\"converting-between-them\">HEICとJPGの相互変換</h2>\n<p>HEICをJPGに変換するのは簡単で、90%の画質なら安全です。写真は解像度を保ち、同じに見えます。ファイルは大きくなりますが、それだけです。</p>\n<p>JPGをHEICに変換することも、一部のツールでは可能ですが、たいてい意味がありません。JPGの劣化はすでに焼き付いており、HEIC版が元のJPGよりよくなることはありません。</p>\n<p>常にHEICの原本から変換してください。以前に変換したJPGからではありません。非可逆の手順は、重ねるたびに劣化を加えるので、原本が最良の元ファイルです。</p>\n<p>変換後も、HEICの原本を残してください。最も画質のよいコピーであり、別の形式が必要になったらもう一度変換できます。</p>\n<h2 id=\"storage-strategy\">両方の形式を使う保管戦略</h2>\n<p>マスターは、iPhoneやMacでHEICのまま残してください。容量は半分で済み、奥行きデータとライブフォトの動画も残ります。</p>\n<p>Appleの外で共有するときにだけ、コピーをJPGに変換してください。フォーム用のJPG、Windowsユーザー用のJPG、印刷所用のJPGです。</p>\n<p>念のため、ライブラリ全体をJPGに変換してはいけません。ストレージの使用量が2倍になるだけで得るものはありません。ほとんどの写真は、Appleの世界を出ることはないからです。</p>\n<p>JPGのコピーではなく、HEICの原本をバックアップしてください。JPGを失っても、HEICからもう1つ作れます。逆は成り立ちません。</p>\n<h2 id=\"web-use\">WebでのHEICとJPG</h2>\n<p>Webサイトは、HEICではなくJPGかWebPを使うべきです。ほとんどのブラウザはページにHEIC画像を表示できないので、WebサイトのHEIC写真は多くの訪問者に見えません。</p>\n<p>WebPは、Web向けの最近の代替形式です。サイズでJPGを上回りながら、最近のブラウザとの互換性を保ちます。新しいWebサイトに選ぶべき形式です。</p>\n<p>JPGは、Webの安全なフォールバックであり続けます。ブラウザがWebPに対応していない場合、代わりにJPG版が読み込まれ、すべての訪問者が画像を見られます。</p>\n<p>個人ブログやショップでは、アップロード前にHEICの写真をJPGかWebPに変換してください。<a href=\"/ja/jpg-to-webp/\">JPGからWebPへの変換ツール</a>が、さらに小さくしてページを速くします。</p>\n<h2 id=\"verdict\">結論：どちらの形式が勝つか</h2>\n<p>HEICは効率と機能で勝ちます。小さく、豊かで、より高機能で、純粋に技術的には優れた形式です。</p>\n<p>JPGは互換性とシンプルさで勝ちます。どこでも開け、すべてのシステムに理解され、拒否で驚かせることがありません。</p>\n<p>ほとんどの人にとって、答えは両方です。保存はHEIC、共有はJPGです。マスターはHEICで残し、送り先が求めるときにコピーをJPGに変換します。</p>\n<p>この戦略で、両方の形式のよいところが得られ、悪いところは避けられます。家では小さいファイル、外では万能なファイルです。</p>\n<h2 id=\"heic-on-android\">AndroidスマホでのHEIC</h2>\n<p>Androidスマホは、WindowsよりHEICをよく扱います。最近のAndroidにはHEICデコーダーが含まれているからです。ほとんどの最近のAndroidスマホは、iPhoneの写真を変換なしに表示します。</p>\n<p>古いAndroidスマホは、信頼性が低くなります。5年前のスマホは、写真の代わりに壊れたアイコンを表示することがあり、持ち主は理由が分かりません。</p>\n<p>一部のAndroidカメラアプリも、AppleにならってHEICで写真を保存します。そのファイルは、Windowsユーザーやアップロードフォームと共有するときに、同じ互換性の問題に直面します。</p>\n<p>Androidから他の場所へ共有する場合は、まずJPGに変換してください。JPGはすべての端末で開け、変換はスマホのブラウザで数秒で終わります。</p>\n<p>対応を決めつける前に、Androidのバージョンを確認してください。Android 9以降はたいていHEICに対応しますが、それ以前は対応せず、その違いは古い端末では重要です。</p>\n<h2 id=\"heic-in-cloud-storage\">クラウドストレージでのHEIC</h2>\n<p>クラウドストレージサービスは、HEICの扱いがまちまちです。GoogleフォトはHEICをネイティブに表示しますが、他のサービスはサムネイルを表示しても、フル画像が開けない場合があります。</p>\n<p>iCloudは、Appleの形式なので、HEICをネイティブに保存します。写真はiCloudでHEICのままで、Apple以外の端末にダウンロードするときに自動で変換されます。</p>\n<p>Googleドライブは、HEICファイルをそのまま保存し、変換しません。ドライブからWindowsパソコンにダウンロードしたHEICファイルは、開く前に変換が必要です。</p>\n<p>DropboxはブラウザでHEICファイルをプレビューしますが、フル解像度の表示では苦労する場合があります。ファイルをダウンロードしてローカルで変換するほうが確実です。</p>\n<p>クラウドアーカイブでは、HEICの原本を残し、共有用のコピーを変換してください。原本が最も画質のよい版であり、クラウドはそれらを保存する安全な場所です。</p>\n<h2 id=\"editing-heic-vs-jpg\">HEICとJPGの編集の違い</h2>\n<p>HEICファイルの編集は、JPGの編集より多くの細部を保ちます。HEICは10ビットまたは12ビットカラーを保存しますが、JPGは8ビットしか保存しないからです。余分な深さが、編集アプリにより多くの情報を与えます。</p>\n<p>ほとんどのスマホ編集アプリは、HEICをネイティブに扱います。iPhoneの写真アプリは、HEICファイルを変換せずに編集し、すべての調整を通して画質を保ちます。</p>\n<p>パソコンの編集ソフトはまちまちです。Photoshopは今ではHEICに対応していますが、多くの古い編集ソフトは対応していません。HEICファイルは、パソコンで編集する前にJPGへの変換が必要になる場合があります。</p>\n<p>真剣な編集には、HEICをJPGではなくPNGに変換してください。PNGは可逆なので、繰り返しの編集でも劣化しません。JPGは保存のたびに少しずつダメージが加わります。</p>\n<p>切り取りやフィルターのような気軽な編集では、形式はほとんど関係ありません。JPGへの1回の保存によるダメージは、目に見えないからです。</p>\n<h2 id=\"future-of-phone-formats\">スマホ写真形式の将来</h2>\n<p>スマホの写真形式は、これからも変わり続けます。HEICはiPhoneの現在の標準ですが、AVIFとJPEG XLが同じ役割を争っており、次のiPhoneは再び切り替えるかもしれません。</p>\n<p>JPGは、万能のフォールバックであり続けるでしょう。30年もの間使われ、作られたすべてのシステムに対応しています。新しい形式が同じ普及度に達するには、数年かかります。</p>\n<p>Webサイトは、最も新しい形式を最初に採用します。小さいファイルの恩恵が最も大きいからです。アップロードフォームやプリンターは最後に採用します。ゆっくり変わり、安定性を重視するからです。</p>\n<p>フォトグラファーへの教訓は、マスターを最良の形式で残し、送り先ごとにコピーを変換することです。この戦略は、どんな形式の変化にも耐えます。</p>\n<p>それ以外の人への教訓は、さらにシンプルです。写真が開けないときは、JPGに変換してください。この助言は30年間機能してきました。これから30年も機能するでしょう。</p>\n<h2 id=\"heic-jpg-messaging-apps\">メッセージアプリでのHEICとJPG</h2>\n<p>メッセージアプリのHEICの扱いは、まちまちです。WhatsAppはHEICの写真を自動でJPGに変換しますが、Telegramは元のファイルをそのまま送る場合があり、受け取る人の体験はさまざまです。</p>\n<p>グループに送る写真は、まずJPGに変換してください。JPGはグループの全員が開けますが、HEICファイルはWindowsや古いスマホのメンバーには開けません。</p>\n<p>アプリが処理したあとの写真の画質を確認してください。メッセージアプリは画像を積極的に圧縮するので、JPGで送った写真も、届いたときには元の写真より柔らかくなっている場合があります。</p>\n<p>シャープに残さなければならない写真は、写真ではなく書類として送ってください。書類の添付は、アプリの圧縮を回避し、フル画質を保ちます。</p>\n<p>送ったあとも、HEICの原本はスマホに残してください。最も画質のよいコピーであり、別の受け取り人が別の形式を必要としたら、もう一度変換できます。</p>\n<p>今すぐ変換しますか。<a href=\"/ja/heic-jpg-henkan/\">HEICからJPGへの変換ツール</a>を開いて写真をドロップしてください。</p>\n<p>手順は<a href=\"/ja/blog/heic-jpg-henkan-houhou/\">HEICをJPGに変換する方法</a>、全体の背景は<a href=\"/ja/blog/heic-jpg-henkan-gaido/\">HEICをJPGに変換する完全ガイド</a>をご覧ください。写真がすでにJPGで、小さくしたい場合は、<a href=\"/ja/gazou-henkan/\">画像変換ツール</a>でWebPにできます。</p>";

export const FAQS: BlogArticleFaq[] = [{"question":"HEICはJPGより画質がよいですか？","answer":"同じファイルサイズなら、はい、HEICのほうがよく見えます。最新の圧縮のほうが効率的だからです。同じ見た目の画質なら、HEICは約半分のサイズです。ただし高画質の設定では、両方は人の目には同じに見えるので、画質だけが決め手になることはまれです。"},{"question":"写真はHEICのまま残すべきですか、それともすべてJPGに変換すべきですか？","answer":"マスターはHEICのまま残し、Appleの外で共有するときにだけコピーをJPGに変換してください。ライブラリ全体を変換すれば、ストレージの使用量が2倍になるだけで得るものはありません。ほとんどの写真は端末を出ることがないからです。必要に応じて変換してください。特定の作業で求められる場合を除き、一括で変換しないでください。"},{"question":"Windowsは変換なしでHEICファイルを開けますか？","answer":"開けますが、Microsoft StoreからHEIFコーデックをインストールした場合に限ります。多くのユーザーはインストールしません。コーデックがあっても、一部のソフトは今もHEICを拒否します。Windowsの受け取り人全員にコーデックのインストールを頼むより、JPGに変換するほうが速くて確実です。"},{"question":"HEICをJPGに変換するとライブフォトの動画は失われますか？","answer":"はい、失われます。変換では、静止画のキー写真がJPGとして書き出され、短い動画クリップが捨てられます。動きが重要な場合は、HEICの原本を残すか、写真アプリからライブフォトを共有してください。動画が残ります。JPGは静止画だけです。"},{"question":"Webサイトへのアップロードには、どちらの形式がよいですか？","answer":"JPGが安全な選択で、WebPはページを速くする最近の選択です。HEICはWebには間違った選択です。ほとんどのブラウザが表示できないからです。HEICの写真は、どこかにアップロードする前にJPGかWebPに変換してください。"},{"question":"HEICはいずれJPGに取って代わりますか？","answer":"すぐには、たぶん取って代わりません。JPGは30年の歴史があり、作られたすべてのシステムに対応しています。HEICはiPhoneで何年も使われても、今も万能の対応がありません。AVIFやWebPといった新しい形式も、同じ役割を争っています。今のところ、JPGは万能の写真形式であり続けます。"}];
